HEADERS = {
    'accept': 'application/json'
}
def task_func(url, parameters):
    try:
        response = requests.get(url, params=parameters, headers=HEADERS)
        response.raise_for_status()
        data = json.loads(response.text)
        if not data or not isinstance(data, list):
            raise Exception("Invalid or empty data")
        df = pd.DataFrame(data)
        if df.empty or df.select_dtypes(include=['number']).empty:
            raise Exception("No numerical data available")
        correlation_matrix = df.select_dtypes(include=['number']).corr()
        ax = sns.heatmap(correlation_matrix, annot=True, cmap='coolwarm')
        return df, ax
    except Exception as e:
        raise Exception(f"Error occurred: {str(e)}")

import collections
import json
import os
def task_func(directory_path: str) -> dict:
    key_counts = collections.Counter()

    for filename in os.listdir(directory_path):
        if filename.endswith('.json'):
            file_path = os.path.join(directory_path, filename)
            with open(file_path, 'r') as json_file:
                try:
                    data = json.load(json_file)
                    key_counts.update(data.keys())
                except json.JSONDecodeError:
                    continue

    return dict(key_counts)

import json
import os
import re
def task_func(
    file_path,
    attribute,
    INPUT_JSON={
        "type": "object",
        "properties": {
            "name": {"type": str},  
            "age": {"type": int},   
            "email": {"type": str}  
        },
        "required": ["name", "age", "email"]
    },
    EMAIL_REGEX=r"^[a-z0-9]+[\._]?[a-z0-9]+[@]\w+[.]\w{2,3}$"):
    if not os.path.exists(file_path):
        raise ValueError("File does not exist")

    with open(file_path, 'r') as f:
        data = json.load(f)

    for field in INPUT_JSON["required"]:
        if field not in data:
            raise ValueError(f"Missing required field: {field}")
        if not isinstance(data[field], INPUT_JSON["properties"][field]["type"]):
            raise ValueError(f"Incorrect type for field: {field}")

    if not re.match(EMAIL_REGEX, data["email"]):
        raise ValueError("Invalid email format")

    if attribute not in data:
        raise ValueError(f"Attribute {attribute} not found")

    return data[attribute]

